import http from "node:http";
import https from "node:https";

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function isDenied(error) {
  for (let current = error; current; current = current.cause) {
    if (current.name === "NotCapable") return true;
    if (current.message?.startsWith("oden capsec:")) return true;
  }
  return false;
}

async function bounded(promise, cleanup = () => {}) {
  try {
    return await Promise.race([
      promise,
      delay(2_000).then(() => {
        throw new Error("probe timed out");
      }),
    ]);
  } finally {
    cleanup();
  }
}

async function expectRoute(name, expected, probe) {
  let denied = false;
  let observed;
  try {
    await probe();
  } catch (error) {
    observed = error;
    denied = isDenied(error);
  }
  const actual = denied ? "denied" : observed ? "failed" : "connected";
  const wanted = expected === "connect" ? "connected" : "denied";
  if (actual !== wanted) {
    throw new Error(
      `${name}: expected ${wanted}, got ${actual}: ${observed?.name}:${observed?.message}`,
      { cause: observed },
    );
  }
  return actual;
}

function request(options, inspect, inspectSocket) {
  let request;
  let complete = false;
  return bounded(
    new Promise((resolve, reject) => {
      request = http.request(options, (response) => {
        try {
          inspect?.(request, response);
        } catch (error) {
          response.destroy(error);
          reject(error);
          return;
        }
        response.resume();
        response.once("end", () => {
          complete = true;
          resolve();
        });
        response.once("error", reject);
      });
      request.once("error", reject);
      request.once("socket", (socket) => {
        try {
          inspectSocket?.(request, socket);
        } catch (error) {
          reject(error);
        }
      });
      request.end();
    }),
    () => {
      if (!complete) request?.destroy();
    },
  );
}

function secureRequest(options) {
  let request;
  let complete = false;
  return bounded(
    new Promise((resolve, reject) => {
      request = https.request(options, (response) => {
        response.resume();
        response.once("end", () => {
          complete = true;
          resolve();
        });
        response.once("error", reject);
      });
      request.once("error", reject);
      request.end();
    }),
    () => {
      if (!complete) request?.destroy();
    },
  );
}

function optionsFor(url, extra = {}) {
  return {
    hostname: url.hostname,
    port: url.port,
    path: `${url.pathname}${url.search}`,
    protocol: url.protocol,
    ...extra,
  };
}

async function expectSocketsClosed(sockets, label) {
  await bounded(Promise.all(sockets.map((socket) => {
    if (socket.destroyed) return Promise.resolve();
    return new Promise((resolve) => socket.once("close", resolve));
  })));
  if (sockets.some((socket) => !socket.destroyed)) {
    throw new Error(`${label} left a protected socket open`);
  }
}

function rawSwitch(options, event) {
  let request;
  let raw;
  return bounded(
    new Promise((resolve, reject) => {
      request = http.request(options);
      request.once("error", reject);
      request.once(event, (_response, socket) => {
        raw = socket;
        socket.once("error", reject);
        socket.once("data", (chunk) => {
          if (String(chunk) !== "ODEN_RAW_WRITE") {
            reject(new Error(`${event}: unexpected echo ${String(chunk)}`));
          } else {
            resolve();
          }
        });
        socket.write("ODEN_RAW_WRITE");
      });
      request.end();
    }),
    () => {
      request?.destroy();
      raw?.destroy();
    },
  );
}

async function keepAliveReuseIsClosed(origin) {
  const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
  const sockets = [];
  const url = new URL(`${origin}/ok`);
  try {
    let reused = false;
    await request(optionsFor(url, { agent }), (req) => {
      sockets.push(req.socket);
    });
    await request(optionsFor(url, { agent }), (req) => {
      sockets.push(req.socket);
      reused = req.reusedSocket;
    });
    if (sockets[0] === sockets[1] || reused) {
      throw new Error("protected-profile keep-alive socket was reused");
    }
  } finally {
    agent.destroy();
  }
}

async function redirect(origin) {
  let location;
  await request(`${origin}/redirect`, (_req, response) => {
    location = response.headers.location;
  });
  if (!location) throw new Error("redirect response omitted Location");
  await request(new URL(location, origin));
}

// @ref LLP 0019#fetch-versus-connect [verifies] -- Every reachable Node HTTP
// socket route is connect-class under `/1.1`, pooling is closed without a
// principal-bound key, and forward proxies are closed without final-peer
// attestation. A fetch grant cannot obtain the object first and mutate, detach,
// delegate, or pool it later.
export async function runNodeHttpSocketRoutes(
  expected,
  endpoints,
  observedRawBytes = () => 0,
  observedConnections = () => 0,
) {
  const url = new URL(`${endpoints.origin}/ok`);
  const routes = [
    ["request-socket-event-property", () => {
      let emittedSocket;
      return request(url, (req) => {
        if (!emittedSocket || req.socket !== emittedSocket) {
          throw new Error("request socket event/property identity unavailable");
        }
      }, (_req, socket) => {
        if (typeof socket.write !== "function") {
          throw new Error(
            "request socket event did not expose a writable Socket",
          );
        }
        emittedSocket = socket;
      });
    }],
    ["response-socket-write", () =>
      request(url, (_req, response) => {
        if (!response.socket?.writable) {
          throw new Error("response socket unavailable");
        }
        response.socket.write("\r\n");
      })],
    ["connect-tunnel-raw-write", () =>
      rawSwitch({
        hostname: url.hostname,
        port: url.port,
        method: "CONNECT",
        path: "target.example:443",
      }, "connect")],
    ["upgrade-raw-write", () =>
      rawSwitch({
        hostname: url.hostname,
        port: url.port,
        path: "/upgrade",
        headers: { connection: "Upgrade", upgrade: "oden-test" },
      }, "upgrade")],
    ["custom-agent", async () => {
      const agent = new http.Agent();
      agent.createConnection = () => {
        throw new Error("closed custom Agent factory was invoked");
      };
      try {
        await request(optionsFor(url, { agent }));
      } finally {
        agent.destroy();
      }
    }, "closed"],
    ["create-connection-hook", () =>
      request(optionsFor(url, {
        agent: null,
        createConnection: () => {
          throw new Error("closed request createConnection hook was invoked");
        },
      })), "closed"],
    ["redirect-hop", () => redirect(endpoints.origin)],
    ["keepalive-reuse-closed", () => keepAliveReuseIsClosed(endpoints.origin)],
    ["forward-proxy-closed", async () => {
      const agent = new http.Agent({
        proxyEnv: { http_proxy: endpoints.proxy },
      });
      try {
        await request(optionsFor(url, { agent }));
      } finally {
        agent.destroy();
      }
    }, "closed"],
    ["https-forward-proxy-closed", async () => {
      const agent = new https.Agent({
        proxyEnv: { https_proxy: endpoints.proxy },
        rejectUnauthorized: false,
      });
      try {
        await secureRequest(optionsFor(
          new URL(`${endpoints.httpsOrigin}/ok`),
          { agent, rejectUnauthorized: false },
        ));
      } finally {
        agent.destroy();
      }
    }, "closed"],
    [
      "unix-socket",
      () => request({ socketPath: endpoints.unixPath, path: "/ok" }),
    ],
  ];

  for (const [name, probe, routeExpected] of routes) {
    const bytesBefore = observedRawBytes();
    const connectionsBefore = observedConnections();
    const outcome = await expectRoute(name, routeExpected ?? expected, probe);
    if (outcome === "denied") await delay(20);
    const bytesAfter = observedRawBytes();
    const connectionsAfter = observedConnections();
    if (outcome === "denied" && bytesAfter !== bytesBefore) {
      throw new Error(
        `${name}: denial followed ${bytesAfter - bytesBefore} raw server byte(s)`,
      );
    }
    if (outcome === "denied" && connectionsAfter !== connectionsBefore) {
      throw new Error(
        `${name}: denial followed ${connectionsAfter - connectionsBefore} server connection(s)`,
      );
    }
    console.log(`NODE_HTTP_SOCKET_ROUTE ${name} ${outcome.toUpperCase()}`);
  }
  console.log(`NODE_HTTP_SOCKET_ROUTES ${expected} PASS`);
}

export async function runQueuedBuiltInReplacement(origin) {
  // coverage-route: queued-built-in-replacement
  const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
  const sockets = [];
  try {
    await Promise.all([
      request(
        optionsFor(new URL(`${origin}/queued-first`), { agent }),
        (req) => sockets.push(req.socket),
      ),
      request(
        optionsFor(new URL(`${origin}/queued-second`), { agent }),
        (req) => sockets.push(req.socket),
      ),
    ]);
    if (sockets.length !== 2 || sockets[0] === sockets[1]) {
      throw new Error(
        "concurrent built-in request did not receive a fresh socket",
      );
    }
    await expectSocketsClosed(sockets, "concurrent built-in requests");
  } finally {
    agent.destroy();
  }
  console.log("NODE_HTTP_SOCKET_ROUTE queued-built-in-replacement CONNECTED");
}

export async function runQueuedBuiltInHttpsReplacement(origin) {
  // coverage-route: queued-built-in-https-replacement
  const agent = new https.Agent({
    keepAlive: true,
    maxSockets: 1,
    rejectUnauthorized: false,
  });
  const sockets = [];
  try {
    await Promise.all([
      request(
        optionsFor(new URL(`${origin}/queued-first`), {
          agent,
          rejectUnauthorized: false,
        }),
        (req) => sockets.push(req.socket),
      ),
      request(
        optionsFor(new URL(`${origin}/queued-second`), {
          agent,
          rejectUnauthorized: false,
        }),
        (req) => sockets.push(req.socket),
      ),
    ]);
    if (sockets.length !== 2 || sockets[0] === sockets[1]) {
      throw new Error(
        "concurrent built-in HTTPS request did not receive a fresh socket",
      );
    }
    await expectSocketsClosed(sockets, "concurrent built-in HTTPS requests");
  } finally {
    agent.destroy();
  }
  console.log(
    "NODE_HTTP_SOCKET_ROUTE queued-built-in-https-replacement CONNECTED",
  );
}

async function expectScheme(name, expected, probe) {
  let result;
  let denied = false;
  try {
    result = await probe();
  } catch (error) {
    denied = isDenied(error);
    if (!denied) throw error;
  }
  if ((expected === "denied") !== denied) {
    throw new Error(
      `${name}: expected ${expected}, got ${denied ? "denied" : result}`,
    );
  }
  return result;
}

function nodeProtocolProbe(protocol, origin) {
  const url = new URL(origin);
  return async () => {
    const agent = new http.Agent();
    // Node trusts this mutable field when comparing the request protocol. The
    // native gate must still prevent a non-network scheme from reaching the
    // agent's real TCP creation path.
    agent.protocol = protocol;
    try {
      await request({
        protocol,
        hostname: url.hostname,
        port: url.port,
        path: "/node-scheme-probe",
        agent,
      });
    } finally {
      agent.destroy();
    }
  };
}

// @ref LLP 0019#fetch-versus-connect [verifies] -- HTTP(S), file, data,
// blob, and unknown schemes share the engine classifier across fetch, loader,
// and Node compatibility paths.
export async function runUrlSchemeMatrix(mode, fileUrl, remoteOrigin) {
  const data = await expectScheme(
    "fetch-data",
    "allowed",
    async () => await (await fetch("data:text/plain,DATA_SCHEME_OK")).text(),
  );
  if (data !== "DATA_SCHEME_OK") throw new Error(`bad data URL body: ${data}`);

  await expectScheme("fetch-blob", "denied", async () => {
    const url = URL.createObjectURL(new Blob(["secret"]));
    try {
      await fetch(url);
    } finally {
      URL.revokeObjectURL(url);
    }
  });
  await expectScheme(
    "fetch-unknown",
    "denied",
    () => fetch("future-transport:secret"),
  );
  for (
    const [name, protocol] of [
      ["node-file", "file:"],
      ["node-data", "data:"],
      ["node-runtime-internal", "node:"],
      ["node-blob", "blob:"],
      ["node-unknown", "future-transport:"],
      ["node-malformed-http", "http::"],
    ]
  ) {
    await expectScheme(
      name,
      "denied",
      nodeProtocolProbe(protocol, remoteOrigin),
    );
  }
  await expectScheme(
    "loader-data",
    "allowed",
    async () =>
      (await import("data:text/javascript,export default 'DATA_IMPORT_OK'"))
        .default,
  );
  await expectScheme("loader-blob", "denied", async () => {
    const url = URL.createObjectURL(
      new Blob(["export default 'blob'"], { type: "text/javascript" }),
    );
    try {
      await import(url);
    } finally {
      URL.revokeObjectURL(url);
    }
  });
  await expectScheme(
    "loader-http",
    "denied",
    () => import(`${remoteOrigin}/module.js`),
  );

  const expectedFile = mode === "file" ? "allowed" : "denied";
  const fileBody = await expectScheme(
    "fetch-file",
    expectedFile,
    async () => await (await fetch(fileUrl)).text(),
  );
  if (mode === "file" && fileBody.trim() !== "FILE_SCHEME_OK") {
    throw new Error(`bad file URL body: ${fileBody}`);
  }
  console.log(`URL_SCHEME_MATRIX ${mode} PASS`);
}
